from jsonb_to_recordset($json$[{"id":"che-so-149","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If the partial pressure of CO2 above a drink is doubled at constant temperature, the dissolved mole fraction of CO2","options":["doubles","halves","becomes four times","stays exactly the same"],"answer_index":0,"explanation":"x ∝ p at fixed T, so doubling p doubles the dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-150","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dry air is 0.21 mole fraction oxygen. With $K_H$(O2) = 3.3 × 10⁷ torr and a total air pressure of 760 torr, dissolved x(O2) is nearest","options":["4.8 × 10⁻⁶","2.1 × 10⁻¹","3.3 × 10⁻⁷","1.6 × 10⁻⁴"],"answer_index":0,"explanation":"p(O2) = 0.21 × 760 = 160 torr; x = 160 / 3.3 × 10⁷ ≈ 4.8 × 10⁻⁶.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-151","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For volatile component A in an ideal liquid mixture, Raoult’s relation is written","options":["$p_A = p_A^\\circ x_A$","$p_A = p_A^\\circ / x_A$","$p_A = p_A^\\circ + x_A$","$p_A = K_H x_A$"],"answer_index":0,"explanation":"Partial pressure equals the pure-liquid vapour pressure times the liquid mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-152","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Total vapour pressure over an ideal binary liquid equals","options":["$p_A^\\circ x_A + p_B^\\circ x_B$","$p_A^\\circ + p_B^\\circ$","$x_A + x_B$","$K_H(x_A + x_B)$"],"answer_index":0,"explanation":"Each component contributes independently: $p_{\\mathrm{total}} = \\sum p_i^\\circ x_i$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-153","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving a non-volatile solute in a pure solvent","options":["lowers the solvent vapour pressure","raises the solvent vapour pressure","leaves the vapour pressure unchanged","always doubles the vapour pressure"],"answer_index":0,"explanation":"Solvent mole fraction falls below 1, so $p = p^\\circ x_{\\mathrm{solvent}} < p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-154","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour in equilibrium with an ideal A–B liquid is richer in the component that has the","options":["higher pure-liquid vapour pressure","lower pure-liquid vapour pressure","larger molar mass only","zero Henry constant"],"answer_index":0,"explanation":"The more volatile liquid (larger $p^\\circ$) contributes a larger partial pressure, so $y > x$ for that component.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-155","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A graph of total vapour pressure against liquid mole fraction for an ideal binary pair is","options":["the straight line joining $p_A^\\circ$ and $p_B^\\circ$","a curve with a maximum","a curve with a minimum","a parabola through the origin"],"answer_index":0,"explanation":"Ideal $p_{\\mathrm{total}}$ varies linearly between the two pure-liquid vapour pressures.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-156","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dalton’s law applied to the vapour above a solution gives the vapour mole fraction of A as","options":["$y_A = p_A / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = 1 - p_A$"],"answer_index":0,"explanation":"Each partial pressure is that component’s mole fraction in the gas times the total pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-157","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Raoult’s law for the solvent becomes exact in the limit of a solution that is","options":["very dilute in solute","very concentrated in solute","frozen solid","an emulsion"],"answer_index":0,"explanation":"The solvent then has $x \\approx 1$ and behaves as a nearly pure liquid obeying Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-158","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A closed flask of pure liquid A at equilibrium exerts","options":["its saturation vapour pressure $p_A^\\circ$","zero pressure","only $K_H$","osmotic pressure"],"answer_index":0,"explanation":"The equilibrium vapour pressure of the pure liquid is the $p^\\circ$ used in Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-159","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When the liquid is pure A ($x_A = 1$), Raoult’s law reduces to","options":["$p_A = p_A^\\circ$","$p_A = 0$","$p_A = K_H$","$p_A = \\pi$"],"answer_index":0,"explanation":"The partial pressure of a pure liquid is just its own vapour pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-160","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two liquids that obey Raoult’s law at every composition are said to form","options":["an ideal solution","an azeotrope in every case","a colloid","a suspension"],"answer_index":0,"explanation":"Ideal solutions follow $p_i = p_i^\\circ x_i$ over the whole composition range.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
